mapper.select:
SELECT

FROM Orders o
         JOIN Accounts a ON a.account_id = o.account_id
         JOIN Instruments i ON i.instrument_id = o.instrument_id
WHERE o.instrument_id = #{instrumentId}
  AND o.side = #{side}::order_side_enum
  AND o.status IN ('NEW'::order_status_enum, 'PARTIALLY_FILLED'::order_status_enum)
  AND o.order_id != #{excludeOrderId}



          AND o.limit_price <= #{crossPrice}
          ORDER BY o.limit_price ASC, o.placed_at ASC



          AND o.limit_price >= #{crossPrice}
          ORDER BY o.limit_price DESC, o.placed_at ASC
